{"command": "cd /tmp/sv-dd2aa99292b447e8ba968c0d38c50ec3/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            key = f\"{name} ({fw['framework']})\"
            for pkg in fw['topLevelPackages']:
                result.setdefault(key, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = get_packages(baseline)
a = get_packages(after)

print('=== CHANGES ===')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            print(f'{proj}: {pkg} {bv} -> {av}')

print()
print('=== UNCHANGED (sample) ===')
count = 0
for proj in sorted(b.keys()):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(bp.keys()):
        if bp.get(pkg) == ap.get(pkg):
            count += 1
print(f'{count} package-project combinations unchanged')
"
